                      "text":  "YAML Recipes Cheat Sheet | Docker \u0026amp; Kubernetes Copy-paste Kubernetes manifest templates for common production patterns. Deployment with Probes Service + Ingress HorizontalPodAutoscaler PVC + StatefulSet ConfigMap + Secret RBAC (Role + RoleBinding) NetworkPolicy Job \u0026amp; CronJob ResourceQuota + LimitRange Deployment with Probes apiVersion: apps/v1 kind: Deployment metadata: name: api namespace: production labels: app: api spec: replicas: 3 selector: matchLabels: app: api template: metadata: labels: app: api spec: serviceAccountName: api-sa securityContext: runAsNonRoot: true runAsUser: 10001 containers: - name: api image: mycompany/api:2.3.1 ports: - containerPort: 8080 resources: requests: cpu: 100m memory: 128Mi limits: cpu: 500m memory: 512Mi livenessProbe: httpGet: path: /health port: 8080 initialDelaySeconds: 15 periodSeconds: 10 readinessProbe: httpGet: path: /ready port: 8080 initialDelaySeconds: 5 periodSeconds: 5 envFrom: - configMapRef: name: api-config - secretRef: name: api-secrets Service + Ingress apiVersion: v1 kind: Service metadata: name: api namespace: production spec: selector: app: api ports: - port: 80 targetPort: 8080 --- apiVersion: networking.k8s.io/v1 kind: Ingress metadata: name: api-ingress namespace: production annotations: cert-manager.io/cluster-issuer: letsencrypt-prod spec: ingressClassName: nginx tls: - hosts: [api.example.com] secretName: api-tls rules: - host: api.example.com http: paths: - path: / pathType: Prefix backend: service: name: api port: number: 80 HorizontalPodAutoscaler apiVersion: autoscaling/v2 kind: HorizontalPodAutoscaler metadata: name: api-hpa namespace: production spec: scaleTargetRef: apiVersion: apps/v1 kind: Deployment name: api minReplicas: 2 maxReplicas: 10 metrics: - type: Resource resource: name: cpu target: type: Utilization averageUtilization: 70 PVC + StatefulSet apiVersion: apps/v1 kind: StatefulSet metadata: name: postgres spec: serviceName: postgres replicas: 1 selector: matchLabels: app: postgres template: metadata: labels: app: postgres spec: containers: - name: postgres image: postgres:16 ports: - containerPort: 5432 env: - name: POSTGRES_PASSWORD valueFrom: secretKeyRef: name: db-creds key: password volumeMounts: - name: data mountPath: /var/lib/postgresql/data volumeClaimTemplates: - metadata: name: data spec: accessModes: [\"ReadWriteOnce\"] storageClassName: gp3 resources: requests: storage: 50Gi ConfigMap + Secret apiVersion: v1 kind: ConfigMap metadata: name: api-config data: LOG_LEVEL: info APP_ENV: production --- apiVersion: v1 kind: Secret metadata: name: api-secrets type: Opaque stringData: DB_PASSWORD: changeme API_KEY: secret-key RBAC (Role + RoleBinding) apiVersion: rbac.authorization.k8s.io/v1 kind: Role metadata: name: pod-reader namespace: production rules: - apiGroups: [\"\"] resources: [\"pods\", \"pods/log\"] verbs: [\"get\", \"list\", \"watch\"] --- apiVersion: rbac.authorization.k8s.io/v1 kind: RoleBinding metadata: name: read-pods namespace: production subjects: - kind: ServiceAccount name: api-sa namespace: production roleRef: kind: Role name: pod-reader apiGroup: rbac.authorization.k8s.io NetworkPolicy apiVersion: networking.k8s.io/v1 kind: NetworkPolicy metadata: name: api-ingress-only namespace: production spec: podSelector: matchLabels: app: api policyTypes: - Ingress ingress: - from: - podSelector: matchLabels: app: frontend ports: - protocol: TCP port: 8080 Job and CronJob apiVersion: batch/v1 kind: Job metadata: name: db-migrate spec: backoffLimit: 3 template: spec: restartPolicy: OnFailure containers: - name: migrate image: mycompany/api:2.3.1 command: [\"python\", \"manage.py\", \"migrate\"] --- apiVersion: batch/v1 kind: CronJob metadata: name: nightly-backup spec: schedule: \"0 2 * * *\" jobTemplate: spec: template: spec: restartPolicy: OnFailure containers: - name: backup image: mycompany/backup:1.0 command: [\"./backup.sh\"] ResourceQuota + LimitRange apiVersion: v1 kind: ResourceQuota metadata: name: prod-quota namespace: production spec: h"
